CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.pirate_wrecks (id SERIAL PRIMARY KEY, pos_x NUMERIC NOT NULL DEFAULT 0, pos_y NUMERIC NOT NULL DEFAULT 0, metal INTEGER NOT NULL DEFAULT 0, energy INTEGER NOT NULL DEFAULT 0, crystals INTEGER NOT NULL DEFAULT 0, fuel INTEGER NOT NULL DEFAULT 0, salvaged_by INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW());